import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { AlertTriangle, Server, Monitor, Cloud, HardDrive, Shield, ExternalLink, CheckCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";

interface Asset {
  id: string;
  name: string;
  type: string;
  ip_address: string | null;
  operating_system: string | null;
  criticality: string;
  owner: string | null;
  department: string | null;
  status: string;
  tags: string[];
  match_reason: string;
}

interface ThreatIOCs {
  cves?: string[];
  ipv4?: string[];
  domains?: string[];
  sha256?: string[];
}

interface Props {
  threatTitle: string;
  threatExcerpt?: string | null;
  iocs?: ThreatIOCs | null;
  severity?: string;
}

const ASSET_TYPE_ICON: Record<string, React.ElementType> = {
  server:   Server,
  endpoint: Monitor,
  cloud:    Cloud,
  storage:  HardDrive,
  network:  Shield,
};

const CRIT_COLOR: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/30",
  high:     "bg-orange-500/15 text-orange-400 border-orange-500/30",
  medium:   "bg-yellow-500/15 text-yellow-400 border-yellow-500/30",
  low:      "bg-slate-500/15 text-slate-400 border-slate-500/30",
};

export function AffectedAssetsPanel({ threatTitle, threatExcerpt, iocs, severity }: Props) {
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [orgDomains, setOrgDomains] = useState<string[]>([]);

  useEffect(() => {
    // Load org settings (company domains) for domain matching
    supabase.from("org_settings").select("company_domains, tech_keywords").limit(1)
      .then(({ data }) => {
        if (data && data.length > 0) setOrgDomains(data[0].company_domains ?? []);
      });
  }, []);

  useEffect(() => {
    async function findAffected() {
      setLoading(true);
      const { data: allAssets } = await supabase
        .from("assets")
        .select("id,name,type,ip_address,operating_system,criticality,owner,department,status,tags,notes")
        .not("status", "eq", "decommissioned");

      if (!allAssets || allAssets.length === 0) { setAssets([]); setLoading(false); return; }

      const threatText = `${threatTitle} ${threatExcerpt ?? ""}`.toLowerCase();
      const matched: Asset[] = [];

      for (const asset of allAssets) {
        const reasons: string[] = [];
        const assetText = `${asset.name} ${asset.operating_system ?? ""} ${(asset.tags ?? []).join(" ")} ${asset.notes ?? ""}`.toLowerCase();

        // 1. IP match — threat IOC IPv4 appears in asset IP range
        if (iocs?.ipv4 && asset.ip_address) {
          const assetIP = asset.ip_address.split("/")[0];
          if (iocs.ipv4.includes(assetIP)) reasons.push(`IP match: ${assetIP}`);
        }

        // 2. CVE match — CVE in threat IOC, asset OS/software referenced in threat text
        if (iocs?.cves && iocs.cves.length > 0) {
          // If the threat text mentions this asset's OS/type, flag it
          const osKeywords = [
            asset.operating_system?.toLowerCase().split(" ")[0] ?? "",
            asset.type?.toLowerCase() ?? "",
          ].filter(Boolean);
          for (const kw of osKeywords) {
            if (kw && threatText.includes(kw)) {
              reasons.push(`OS/type match: ${kw} referenced in threat (${iocs.cves[0]})`);
              break;
            }
          }
          // If the asset tags include a known software mentioned in the CVE title
          for (const tag of (asset.tags ?? [])) {
            if (threatText.includes(tag.toLowerCase())) {
              reasons.push(`Tag match: "${tag}" found in threat`);
              break;
            }
          }
        }

        // 3. Domain match — threat domain IOC matches a company domain
        if (iocs?.domains && orgDomains.length > 0) {
          for (const iocDomain of iocs.domains) {
            for (const orgDomain of orgDomains) {
              if (iocDomain.includes(orgDomain) || orgDomain.includes(iocDomain)) {
                reasons.push(`Domain match: ${iocDomain} ≈ ${orgDomain}`);
              }
            }
          }
        }

        // 4. Keyword match — threat text mentions asset name or known tech tags
        if (assetText && threatText) {
          const assetWords = asset.name.toLowerCase().split(/\s+/).filter(w => w.length > 4);
          for (const w of assetWords) {
            if (threatText.includes(w)) { reasons.push(`Name keyword: "${w}"`); break; }
          }
        }

        if (reasons.length > 0) {
          matched.push({ ...asset, tags: asset.tags ?? [], match_reason: reasons.join("; ") });
        }
      }

      // Sort by criticality
      const critOrder: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };
      matched.sort((a, b) => (critOrder[a.criticality] ?? 9) - (critOrder[b.criticality] ?? 9));
      setAssets(matched);
      setLoading(false);
    }
    findAffected();
  }, [threatTitle, threatExcerpt, iocs, orgDomains]);

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-4 text-sm text-slate-500">
        <div className="h-3 w-3 rounded-full border border-cyan-500/40 animate-spin" />
        Scanning asset inventory…
      </div>
    );
  }

  if (assets.length === 0) {
    return (
      <div className="flex flex-col items-center gap-2 py-6 text-center">
        <CheckCircle className="h-8 w-8 text-emerald-500/60" />
        <p className="text-sm font-medium text-slate-400">No matching assets found</p>
        <p className="text-xs text-slate-600">
          No assets in your inventory match the IOCs, CVEs, or tech stack referenced in this threat.
        </p>
        <p className="text-[10px] text-slate-700 mt-1">
          Add your company domains in <span className="text-cyan-500">Settings → Org Profile</span> for better matching.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 mb-3">
        <AlertTriangle className="h-4 w-4 text-orange-400" />
        <span className="text-sm font-semibold text-orange-400">{assets.length} potentially affected asset{assets.length !== 1 ? "s" : ""}</span>
        {severity === "critical" && (
          <span className="text-[9px] font-bold px-1.5 py-0.5 rounded border bg-red-500/15 text-red-400 border-red-500/30 ml-auto">
            CRITICAL THREAT
          </span>
        )}
      </div>

      {assets.map(asset => {
        const Icon = ASSET_TYPE_ICON[asset.type] ?? Server;
        return (
          <div
            key={asset.id}
            className="rounded-lg px-3 py-2.5"
            style={{ background: "rgba(245,158,11,0.05)", border: "1px solid rgba(245,158,11,0.12)" }}
          >
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md"
                style={{ background: "rgba(245,158,11,0.1)", border: "1px solid rgba(245,158,11,0.2)" }}>
                <Icon className="h-3.5 w-3.5 text-amber-400" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-slate-200 truncate">{asset.name}</span>
                  <span className={`text-[9px] font-bold px-1 py-0.5 rounded border ${CRIT_COLOR[asset.criticality] ?? CRIT_COLOR.low}`}>
                    {asset.criticality?.toUpperCase()}
                  </span>
                </div>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-[10px] text-slate-500">{asset.type}</span>
                  {asset.ip_address && <span className="text-[10px] text-slate-600">· {asset.ip_address}</span>}
                  {asset.department && <span className="text-[10px] text-slate-600">· {asset.department}</span>}
                </div>
              </div>
            </div>
            <div className="mt-2 text-[10px] text-amber-400/80 bg-amber-500/5 rounded px-2 py-1 border border-amber-500/10">
              ⚡ {asset.match_reason}
            </div>
          </div>
        );
      })}

      <a href="/assets" className="flex items-center gap-1 text-[10px] text-cyan-500 hover:text-cyan-400 transition-colors mt-1">
        <ExternalLink className="h-3 w-3" />
        View full asset inventory
      </a>
    </div>
  );
}
